/**
 * `nivo-gtm.social-calendar-read` (Đọc nội dung chờ lên lịch): a decision node. It reads the approved `gtm.content` items that have no publication yet, and last week's metrics, so the plan places only what is ready.
 */
class SocialCalendarRead {
    run(input, reach) {
        const approved = reach.objects("gtm.content").query({ where: { status: "approved" }, sort: { by: "updatedAt", direction: "asc" }, limit: 50 });
        if (approved.error)
            throw approved.error;
        const planned = reach.objects("gtm.publication").query({ where: { status: { in: ["planned", "scheduled", "published"] } }, limit: 200 });
        if (planned.error)
            throw planned.error;
        const taken = planned.result.items.map((item) => String(item.values.content));
        const items = approved.result.items
            .filter((item) => !taken.includes(String(item.id)))
            .slice(0, reach.settings.maxItems)
            .map((item) => ({ id: String(item.id), code: item.values.code, title: item.values.title, kind: item.values.kind, caption: (item.values.caption ?? "").slice(0, 400) }));
        const published = reach.objects("gtm.publication").query({ where: { status: "published" }, sort: { by: "at", direction: "desc" }, limit: 10 });
        if (published.error)
            throw published.error;
        const metrics = published.result.items.map((item) => ({ channel: item.values.channel, views: item.values.views ?? 0, engagements: item.values.engagements ?? 0, leads: item.values.leads ?? 0 }));
        return { instant: input.instant, items, metrics };
    }
}

