/** An instant plus whole hours, as ISO text with the `Z` offset an object datetime field takes. */
const addHours = (iso, hours) => new Date(Date.parse(iso) + hours * 3_600_000).toISOString();

/** The day of an instant without dashes (`2026-11-18T08:00:00Z` is `20261118`), the stem of a content code. */
const compactDay = (iso) => iso.slice(0, 10).replace(/-/gu, "");

/** The owner an idea has until a person picks it: the Studio agent itself. */
const STUDIO = "nivo-gtm.studio";

/** A text cut to a length (a card or a field has a limit), with an ellipsis when it was cut. */
const clip = (text, length) => (text.length <= length ? text : `${text.slice(0, length - 1)}…`);

/**
 * `nivo-gtm.studio-file-ideas` (Ghi ý tưởng): one act, `object.create` of one `gtm.content` per idea (status `idea`, owner the Studio agent, the next action "Chọn ý tưởng" due in `pickHours`). A code is
 * `CT-<yyyymmdd>-<n>`, so a rerun of the round finds its own rows (`OBJECTS_VALUE_TAKEN`) and files nothing twice. The card text and its choices (Chọn per idea, Bỏ cả tuần) are made here, from the codes.
 */
class StudioFileIdeas {
    run(input, reach) {
        const day = compactDay(input.instant);
        const nextAt = addHours(input.instant, reach.settings.pickHours);
        const codes = [];
        const lines = [];
        const choices = [];
        input.ideas.forEach((idea, at) => {
            const code = `CT-${day}-${String(at + 1)}`;
            const { error } = reach.objects("gtm.content").create({
                code,
                kind: idea.format,
                title: idea.title,
                status: "idea",
                pillar: idea.pillar,
                hook: idea.hook,
                owner: STUDIO,
                nextAction: "Chọn ý tưởng",
                nextAt,
            });
            // a rerun of the same round: the row is there already, nothing is filed twice
            if (error && error.code !== "OBJECTS_VALUE_TAKEN")
                throw error;
            codes.push(code);
            lines.push(`${String(at + 1)}. [${idea.format === "video" ? "Video" : "Bài viết"}] ${idea.title}\n   Mở đầu: ${idea.hook}\n   Góc: ${idea.angle}\n   Cho: ${idea.segment}. Vì sao bây giờ: ${idea.whyNow}`);
            choices.push({ value: `idea-choose:${code}`, label: `Chọn ${String(at + 1)}` });
        });
        choices.push({ value: `idea-drop:${day}`, label: "Bỏ cả tuần" });
