            prompt: `${STUDIO_POLICY}\n\n${GOAL}`,
            data: { title: got.result.values.title, script: (got.result.values.script ?? {}), caption: got.result.values.caption ?? "" },
        });
        if (error)
            throw error;
        return result.value;
    }
}

StudioShotList;

// Small pure helpers the cells inline (the compiler copies each helper a cell references into its stored text). No package import here: a stored cell imports nothing.
/** An ISO instant `hours` after `at` (an ISO instant). */
const plusHours = (at, hours) => new Date(Date.parse(at) + hours * 3600000).toISOString();

/**
 * `nivo-gtm.update-deal` (Cập nhật đơn bán): ONE act, `object.update` of the `gtm.deal`: a status, the money fields, the responsibility fields (next action, due time, evidence) and, on request, the time
 * of payment or activation. It reads the deal first for the version it updates against. Every status change of a deal in this package goes through this cell.
 */
class UpdateDeal {
    run(input, reach) {
        const deal = reach.objects("gtm.deal").get(input.dealId);
        if (deal.error)
            throw deal.error;
        const { result, error } = reach.objects("gtm.deal").update({
            id: input.dealId,
            version: deal.result.version,
            values: {
                ...(input.status === undefined ? {} : { status: input.status }),
                ...(input.amount === undefined ? {} : { amount: input.amount }),
                ...(input.discountPercent === undefined ? {} : { discountPercent: input.discountPercent }),
                ...(input.payCode === undefined ? {} : { payCode: input.payCode }),
                ...(input.sepayRef === undefined ? {} : { sepayRef: input.sepayRef }),
                ...(input.nextAction === undefined ? {} : { nextAction: input.nextAction }),
                ...(input.nextInHours === undefined ? {} : { nextAt: plusHours(reach.facts.at, input.nextInHours) }),
                ...(input.evidence === undefined ? {} : { evidence: input.evidence }),
                ...(input.stamp === "paid" ? { paidAt: reach.facts.at } : {}),
                ...(input.stamp === "activated" ? { activatedAt: reach.facts.at } : {}),
            },
        });
        if (error)
            throw error;
        return { version: result.version };
    }
}

UpdateDeal;

/** `nivo-gtm.update-lead` (Cập nhật khách tiềm năng): ONE act, `object.update` of the `gtm.lead`: its stage, its next action and the evidence of the move. Deals uses it to mark a lead `won`. */
class UpdateLead {
    run(input, reach) {
        const lead = reach.objects("gtm.lead").get(input.leadId);
        if (lead.error)
            throw lead.error;
        const { result, error } = reach.objects("gtm.lead").update({
            id: input.leadId,
            version: lead.result.version,
            values: { stage: input.stage, nextAction: input.nextAction, evidence: input.evidence },
        });
        if (error)
            throw error;
        return { version: result.version };
    }
}

UpdateLead;

